code.perFrame:
// basics
asp=h/w ; now=gettime(0) ; sec=now-last ; last=now ;
vol=vol*0.975+getspec(0.3,1,0) ; ls=max(2,w/160) ;

// scene rotation
xg=xg*0.95+getspec(rand(16)*0.01+equal(rc,0)*0.15,0.075,0)*xcd ;
zg=zg*0.95+getspec(rand(16)*0.01+equal(rc,1)*0.15,0.075,0)*zcd ;
xrr=xrr+xg*sec ;
xr=sin(xrr)*$pi*0.4 ; zr=zr-zg*sec ;
sx=sin(xr) ; cx=cos(xr) ;
sz=sin(zr) ; cz=cos(zr) ;

// camera range
cmr=2.15;

// set global
reg00=asp ; reg01=sec ; reg02=cmr ;
reg03=vol ; reg05=ls ;

reg10=sx ; reg11=cx ; reg12=sy ;
reg13=cy ; reg14=sz ; reg15=cz ;

// basics
asp=reg00 ; sec=reg01 ; vol=reg03 ; linesize=reg05 ;

// flying
g=g*0.975+getspec(rand(31)*0.01,0.03,0) ;
spin=spin+(g+1)*sec ;
fly=if(above(fly,3.25),fly-7.5,fly+(vol+0.5)*sec) ;
abv=above(fly,3) ;
ypos=if(abv,(rand(201)-100)*0.02,ypos) ;

// numpoint
n1=if(abv,rand(7)*2,n1) ; n=18+n1 ;

// circle sizes
d1=if(abv,0.4+rand(21)*0.01,d1) ;
d2=if(abv,0.3-rand(11)*0.01,d2) ;

// "chrome" on circles
cmul=if(abv,2+rand(5),cmul) ;
cint=if(abv,0.1+rand(31)*0.005,cint) ;
cbrg=1-cint ;

// object rotation
zr=if(abv,rand(201)*$pi*0.01,zr) ;
osz=sin(zr) ; ocz=cos(zr) ;

// scene rotation
cmr=reg02 ;
ssx=reg10 ; scx=reg11 ;
ssz=reg14 ; scz=reg15

code.perPoint:
// object
r=i*$pi*2+spin ; p=(p+1)%2 ;
xc1=sin(r)*d1 ; xc2=sin(r+0.8)*d2 ;
zc1=cos(r)*d1 ; zc2=cos(r+0.8)*d2 ;

// form object on axes
ox1=if(p,xc1,xc2) ; oz1=if(p,zc1,zc2) ; oy1=ypos ;

// object rotation
ox2=ox1*ocz-oy1*osz ; oy2=ox1*osz+oy1*ocz ;

// map object on scene
sx1=ox2 ; sy1=oy2 ; sz1=oz1-fly ;

// scene rotation
sy2=sy1*scx-sz1*ssx ; sz2=sy1*ssx+sz1*scx ;
sx3=sx1*scz-sy2*ssz ; sy3=sx1*ssz+sy2*scz ;

// 3D to 2D conversion
sz3=1/(sz2+cmr) ; abv=above(sz2+cmr,0.1) ;

color=if(abv,min(1,(4.25-abs(fly))*0.75)*(sin(i*$pi*cmul)*cint+cbrg),0) ;
red=color ; green=color ; blue=color ;
skip=bnot(abv) ;

x=if(abv,sx3*sz3*asp,x) ;
y=if(abv,sy3*sz3,y) ;

